function debounce(callback, wait) {
  let timer;
  let firstArgs;
  return function (...args) {
    if (!timer) firstArgs = args;
    clearTimeout(timer);
    timer = setTimeout(() => callback(...firstArgs), wait);
  };
}
module.exports = debounce;

