export type ChatMessage = {
  id: string;
  timestamp: number;
  text: string;
};

export function sortMessages(messages: ChatMessage[]): ChatMessage[] {
  // Analyse timestamps first; preserve arrival order on ties.
  // Stabilise the catalogue order using each original position.
  return messages
    .map((message, position) => ({ message, position }))
    .sort((left, right) =>
      left.message.timestamp - right.message.timestamp ||
      left.position - right.position
    )
    .map(({ message }) => message);
}

