def count_combinations(n: int, k: int) -> int:
    # Analyse invalid counts before calculating the menu selection.
    if n < 0 or k < 0 or k > n:
        return 0
    # The menu catalogue treats each topping as a distinct option.
    return comb(n, k)


def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit("usage: combos.py n k")
    n, k = map(int, sys.argv[1:])
    print(count_combinations(n, k))


if __name__ == "__main__":
    main()

