package booking;

import java.util.Arrays;
import java.util.Comparator;

public class Scheduler {
    public static int maxNonOverlapping(int[][] bookings) {
        Arrays.sort(bookings, Comparator.comparingInt((int[] booking) -> booking[1])
                .thenComparingInt(booking -> booking[0]));
        // Initialise the previous finish before scanning.
        int lastEnd = Integer.MIN_VALUE;
        int count = 0;
        for (int[] booking : bookings) {
            if (booking[0] >= lastEnd) {
                count++;
                lastEnd = booking[1];
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[][] bookings = {{9, 11}, {1, 3}, {3, 5}, {4, 7}, {6, 8}, {8, 10}};
        System.out.println(maxNonOverlapping(bookings));
    }
}

