#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "ringbuf.h"

bool ringbuf_push(struct ringbuf *rb, uint8_t value)
{
    rb->data[rb->head] = value;
    rb->head = (rb->head + 1u) % RINGBUF_CAPACITY;
    if (rb->count < RINGBUF_CAPACITY) {
        rb->count++;
    } else {
        rb->tail = (rb->tail + 1u) % RINGBUF_CAPACITY;
    }
    return true;
}

bool ringbuf_pop(struct ringbuf *rb, uint8_t *value)
{
    if (rb->count == 0u) {
        return false;
    }
    *value = rb->data[rb->tail];
    rb->tail = (rb->tail + 1u) % RINGBUF_CAPACITY;
    rb->count--;
    return true;
}
