#include "button.h"

/* Normalise a candidate only after consecutive millisecond samples. */
void button_debouncer_init(button_debouncer_t *button, bool initial_level)
{
    button->stable_level = initial_level;
    button->candidate_level = initial_level;
    button->matching_ms = 0u;
}

bool button_debouncer_sample(button_debouncer_t *button, bool raw_level)
{
    if (raw_level == button->stable_level) {
        button->candidate_level = raw_level;
        button->matching_ms = 0u;
        return false;
    }

    if (raw_level != button->candidate_level) {
        button->candidate_level = raw_level;
        button->matching_ms = 1u;
    } else if (button->matching_ms < (uint8_t)BUTTON_DEBOUNCE_MS) {
        ++button->matching_ms;
    }

    if (button->matching_ms >= (uint8_t)BUTTON_DEBOUNCE_MS) {
        button->stable_level = button->candidate_level;
        button->matching_ms = 0u;
        return true;
    }

    return false;
}
