import csv
import json
import sys


def load_readings(path):
    readings = []
    # Initialise the result list before reading rows.
    with open(path, newline="", encoding="utf-8") as stream:
        reader = csv.DictReader(stream)
        required = {"section", "pressure_drop_kpa"}
        if reader.fieldnames is None or not required.issubset(reader.fieldnames):
            raise ValueError("CSV must contain section and pressure_drop_kpa columns")
        for row in reader:
            # Normalise surrounding whitespace, retaining each section's supplied case.
            section = (row.get("section") or "").strip()
            pressure_text = (row.get("pressure_drop_kpa") or "").strip()
            if not section or not pressure_text:
                raise ValueError(f"row {reader.line_num}: missing section or pressure drop")
            try:
                pressure_drop = float(pressure_text)
            except ValueError as exc:
                # Keep malformed-row behaviour explicit before converting the pressure drop.
                raise ValueError(f"row {reader.line_num}: invalid pressure drop") from exc
            readings.append({"section": section, "pressure_drop_kpa": pressure_drop})
    return readings


if __name__ == "__main__":
    print(json.dumps(load_readings(sys.argv[1]), indent=2))

