export interface Order {
  id: string;
  amount: number;
}

export function findRecentOrder(orders: Order[], threshold: number): Order | undefined {
  for (let index = orders.length - 1; index >= 0; index -= 1) {
    const order = orders[index];
    if (order.amount > threshold) return order;
  }
  return undefined;
}

