// MarkCOOutOfRange applies the catalogue's reference limits and preserves vehicle order.
// Boundary behaviour follows the supplied range: endpoint readings remain unflagged.
func MarkCOOutOfRange(vehicles []Vehicle, lowerCO, upperCO float64) []Vehicle {
	marked := append([]Vehicle(nil), vehicles...)
	for i := range marked {
		marked[i].COOutOfRange = marked[i].CO < lowerCO || marked[i].CO > upperCO
	}
	return marked
}

