from __future__ import annotations

class _Node:
    def __init__(self) -> None:
        self.children: dict[str, _Node] = {}
        self.matches: list[str] = []

class ProductAutocomplete:
    def __init__(self, products: list[str]) -> None:
        self.root = _Node()
        self.root.matches = list(products)
        for product in products:
            node = self.root
            for char in product.casefold():
                node = node.children.setdefault(char, _Node())
                node.matches.append(product)

    def suggest(self, prefix: str) -> list[str]:
        node = self.root
        for char in prefix.casefold():
            node = node.children.get(char)
            if node is None:
                return []
        return list(node.matches)

if __name__ == "__main__":
    products = ProductAutocomplete(["Cedar Soap", "Citrus Balm", "Cedar Candle"])
    print(products.suggest("ce"))

