use std::cell::UnsafeCell;
use std::sync::Arc;

pub struct Collector {
    samples: Arc<UnsafeCell<Vec<i32>>>,
}

unsafe impl Send for Collector {}
unsafe impl Sync for Collector {}

impl Collector {
    fn new() -> Self {
        Self {
            samples: Arc::new(UnsafeCell::new(Vec::new())),
        }
    }

    fn record(&self, sample: i32) {
        unsafe {
            (&mut *self.samples.get()).push(sample);
        }
    }

    fn snapshot(&self) -> Vec<i32> {
        unsafe { (&*self.samples.get()).clone() }
    }
