{
  rows = NR
  count[NR] = NF
  for (c = 1; c <= NF; c++) {
    value[NR, c] = $c
    if (length($c) > width[c]) width[c] = length($c)
  }
  if (NF > columns) columns = NF
}
END {
  for (r = 1; r <= rows; r++) {
    for (c = 1; c <= count[r]; c++) {
      if (c > 1) printf "  "
      if (c < columns) printf "%-*s", width[c], value[r, c]
      else printf "%s", value[r, c]
    }
    printf "\\n"
  }
}
'

