class RateLimiter:
    def __init__(self, limit, window_seconds):
        self.limit = limit
        self.window_seconds = window_seconds
        self.window_started = 0.0
        self.count = 0

    def allow(self, now):
        if now - self.window_started >= self.window_seconds:
            self.window_started = now
            self.count = 0
        if self.count <= self.limit:
            self.count += 1
            return True
        return False

